30	MG_RCV_01	最後一次進貨價格表	\N	SELECT A.*,M.RCV_DATE,M.RCV_NO,S.SUP_NAME,P.PRD_NAME,S1.*\nFROM TBL_TRANSACTION A\nINNER JOIN TBL_PO_RECV M ON A.TRN_SRC_NO=M.RCV_NO\nINNER JOIN TBL_SUPPLIER S ON M.SUP_NO=S.SUP_NO\nINNER JOIN TBL_PRODUCT P ON A.PRD_NO=P.PRD_NO\n,\n( SELECT PRD_NO,MAX(TO_CHAR(TRN_DATETIME,'YYYY-MM-DD HH24:MI:SS')||LPAD(TRN_ID::text,10)) TRN_DATE\n  FROM TBL_TRANSACTION\n  WHERE TRN_TYPE=1\n  GROUP BY PRD_NO\n) B\n,TBL_SYS_PARAM S1	WHERE A.TRN_TYPE=1\n  AND A.PRD_NO=B.PRD_NO\n  AND (TO_CHAR(A.TRN_DATETIME,'YYYY-MM-DD HH24:MI:SS')||LPAD(A.TRN_ID::text,10))=B.TRN_DATE	\N	          	{"ReportVersion": "2026.3.3", "ReportGuid": "97c52dca342546b3aa3b11ecdb66effb", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607069+0800)/", "ReportChanged": "/Date(1789097607069+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "trn_id", "NameInSource": "trn_id", "Alias": "trn_id", "Type": "System.Int32"}, "1": {"Name": "prd_no", "NameInSource": "prd_no", "Alias": "prd_no", "Type": "System.String"}, "2": {"Name": "inv_no", "NameInSource": "inv_no", "Alias": "inv_no", "Type": "System.String"}, "3": {"Name": "trn_type", "NameInSource": "trn_type", "Alias": "t