36	ST_RPT_02	產品績效分析表	\N	SELECT\r\nD.PRD_NO\r\n, CASE SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)\r\n  WHEN 0 THEN 0\r\n  ELSE ((SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)-SUM(D.SMD_QTY*D.SMD_COST))/SUM(D.SMD_QTY*D.SMD_UNIT_PRICE))*100\r\n  END C_RATE\r\n,P.PRD_NAME\r\n,SUM(D.SMD_QTY) C_QTY\r\n,SUM(D.SMD_QTY*D.SMD_UNIT_PRICE) C_TOTAL\r\n,SUM(D.SMD_QTY*D.SMD_COST) C_COST\r\n,SUM(D.SMD_QTY*D.SMD_UNIT_PRICE)-SUM(D.SMD_QTY*D.SMD_COST) C_PROFIT\r\n,S.SPR_COR_NAME,S.SPR_TEL,S.SPR_FAX\r\nFROM TBL_SHIP M INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\nINNER JOIN TBL_EMPLOYE E ON M.EPY_NO=E.EPY_NO\r\n,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0  	GROUP BY D.PRD_NO,P.PRD_NAME\r\n,S.SPR_COR_NAME,S.SPR_TEL,S.SPR_FAX	\N	{"ReportVersion": "2026.3.3", "ReportGuid": "37b50716219541e7bcb3e1002ec56dcf", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607216+0800)/", "ReportChanged": "/Date(1789097607216+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "prd_no", "NameInSource": "prd_no", "Alias": "prd_no", "Type": "System.String"}, "1": {"Name": "c_rate", "NameInSource": "c_rate", "Alias": "c_rate", "Type": "System.Decimal"}, "2": {"Name": "prd_name", "NameInSource": "prd_name", "Alias": "prd_name", "Type": "System.String"}, "3": {"Name": "c_qty", "NameInSource": "c_qty", "Alias": "c_qty", "Type": "System.Decimal"}, "4": {"Name": "c_total", "NameInSource": "c_total", "Alias": "c_total", "Type": "System.Decimal"}, "5": {"Name": "c_cost", "NameInSource": "c_cost", "Alias": "c_cost", "Type": "System.Decimal"}, "6": {"Name": "c_profit", "NameInSource": "c_profit", "Alias": "c_profit", "Type": "System.Decimal"}, "7": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}, "8": {"Name": "spr_tel", "NameInSource": "spr_tel", "Alias": "spr_tel", "Type": "System.String"}, "9": {"Name": "spr_fax", "NameInSource": "spr_fax", "Alias": "spr_fax", "Type": "System.String"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "527dfe05666b43168a84cf594511fe82", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiPageHeaderBand", "Name": "ppHeaderBand1", "Guid": "276127ed918744c7b01449b5bc00f83e", "CanGrow": true, "ClientRectangle": "0,0.0,19.7379,3.6248", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiText", "Name": "ppLabel2", "Guid": "3e9bcd0fb9c34e19a55c259609405512", "ClientRectangle": "0.635,0.4498,1.7727,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "製表日期："}, "Type": "Expression", "Font": ";10;;", "Border": ";;;;;;;solid:Black", "Brush": "solid:", "TextBrush": "solid:Black"}, "1": {"Ident": "StiText", "Name": "ppSystemVariable1", "Guid": "8eb5359af52d483f894d40b96d4d19a2", "ClientRectangle": "2.4342,0.4498,1.4288,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "{PageNumber}"}, "Type": "Expression", "Font": ";10;;", "Border": ";;;;;;;solid:Black", "Brush": "solid:", "TextBrush": "solid:Black"}, "2":