19	MG_AP_002	應付帳款明細表(已)	\N	SELECT M.RCV_TOTAL+M.RCV_TAX-M.RCV_NOT_CLEAN C_RECEVIED\r\n,P.PRD_UNIT,D.RCD_QTY*RCD_UNIT_PRICE C_SUB_TOTAL\r\n,M.RCV_TOTAL+M.RCV_TAX C_AMOUNT\r\n,COALESCE(D.RCD_PRD_NAME,P.PRD_NAME)C_PRD_NAME\r\n,M.RCV_TAX/T1.CNT C_AVG_TAX\r\n,(M.RCV_TOTAL+M.RCV_TAX-M.RCV_NOT_CLEAN) /T1.CNT C_AVG_RECEIVED\r\n,M.RCV_NOT_CLEAN/T1.CNT C_AVG_NOT_CLEAN\r\n,(M.RCV_TOTAL+M.RCV_TAX) /T1.CNT C_AVG_AMOUNT\r\n,T1.CNT\r\n,M.* ,D.*,C.*,S.*\r\nFROM TBL_PO_RECV M INNER JOIN TBL_PO_RECV_DT D ON M.RCV_NO=D.RCV_NO\r\nINNER JOIN TBL_SUPPLIER C ON M.SUP_NO=C.SUP_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\nINNER JOIN (SELECT M.RCV_NO,COUNT(*)CNT\r\n            FROM TBL_PO_RECV M INNER JOIN TBL_PO_RECV_DT D ON M.RCV_NO=D.RCV_NO\r\n            GROUP BY M.RCV_NO)T1 ON M.RCV_NO=T1.RCV_NO\r\n,TBL_SYS_PARAM S	WHERE M.RCV_STATUS>0\r\n	\N	ORDER BY M.SUP_NO,M.RCV_DATE,M.RCV_NO,D.RCD_SEQNO	{"ReportVersion": "2026.3.3", "ReportGuid": "60bd9b3d35ef43218b21e04da2fe2d58", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097606818+0800)/", "ReportChanged": "/Date(1789097606818+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "c_recevied", "NameInSource": "c_rec