38	ST_RPT_04	月銷售業績統計圖	\N	SELECT  TO_CHAR(M.SMT_DATE,'YYYY/MM') AS MONTH\n,SUM(SMT_TOTAL) AMOUNT\n,S.SPR_COR_NAME\nFROM TBL_SHIP M,TBL_SYS_PARAM S	WHERE M.SMT_STATUS>0	GROUP BY  TO_CHAR(M.SMT_DATE,'YYYY/MM')\n,S.SPR_COR_NAME	ORDER BY MONTH	{"ReportVersion": "2026.3.3", "ReportGuid": "5dcb323694a14b1686b682f8383fbe64", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607258+0800)/", "ReportChanged": "/Date(1789097607258+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "month", "NameInSource": "month", "Alias": "month", "Type": "System.String"}, "1": {"Name": "amount", "NameInSource": "amount", "Alias": "amount", "Type": "System.Decimal"}, "2": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "abca7b8470624daca6ecf3034feaabd5", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiPageHeaderBand", "Name": "ppHeaderBand1", "Guid": "39927d73eed9497aaed89961de32845a", "CanGrow": true, "ClientRectangle": "0,0.0,19.7379,9.7102", "Interaction": {"Ident": "St