48	ST_RPT_12	車輛送貨金額統計表	\N	SELECT CAR_NO,SMT_DATE\n,SUM(TOTAL) TOTAL,SUM(RETURN_TOTAL) RETURN_TOTAL\nFROM\n(\nSELECT A.SMT_NO,B.SMD_SEQNO,C.CAR_NO,C.CAR_LICENSE_NO,A.SMT_DATE::date SMT_DATE ,B.SMD_QTY*B.SMD_UNIT_PRICE TOTAL,0 RETURN_TOTAL\nFROM TBL_SHIP A\nINNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\nINNER JOIN TBL_CAR C ON A.CAR_NO = C.CAR_NO\nWHERE B.SMD_QTY >0\nUNION\nSELECT  A.SMT_NO,B.SMD_SEQNO,C.CAR_NO,C.CAR_LICENSE_NO,A.SMT_DATE::date SMT_DATE ,0,B.SMD_QTY*B.SMD_UNIT_PRICE RETURN_TOTAL\nFROM TBL_SHIP A\nINNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\nINNER JOIN TBL_CAR C ON A.CAR_NO = C.CAR_NO\nWHERE B.SMD_QTY <0\n) A	\N	GROUP BY CAR_NO,SMT_DATE       	ORDER BY A.CAR_NO	{"ReportVersion": "2026.3.3", "ReportGuid": "536ec4b3862142beb8af7aef860879d1", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607467+0800)/", "ReportChanged": "/Date(1789097607467+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "car_no", "NameInSource": "car_no", "Alias": "car_no", "Type": "System.String"}, "1": {"Name": "smt_date", "NameInSource": "smt_date", "Alias": "smt_date", "Type": "System.DateTime"}, "2": {"Name": "total", "NameInSource": "total", "Alias": "to