33	ST_RPT_01	內部業務員績效報表	\N	SELECT\r\nC_SUB_TOTAL-C_COST C_PROFIT\r\n,C_SUB_TOTAL * SPR_BONUS_SALE_RATE C_BONUS_SALE\r\n,(C_SUB_TOTAL-C_COST) * SPR_BONUS_PROFIT_RATE C_BONUS_PROFIT\r\n,(C_SUB_TOTAL * SPR_BONUS_SALE_RATE)+((C_SUB_TOTAL-C_COST) * SPR_BONUS_PROFIT_RATE) C_BONUS_ALL\r\n,T.*\r\nFROM\r\n(\r\nSELECT E.EPY_NAME\r\n,D.SMD_QTY*SMD_UNIT_PRICE C_SUB_TOTAL\r\n,(D.SMD_QTY*D.SMD_COST)*(1+P.PRD_EXT_COST_RATIO) C_COST\r\n,COALESCE(D.SMD_PRD_NAME,P.PRD_NAME)C_PRD_NAME\r\n,M.*\r\n,D.SMD_SEQNO,D.PRD_NO,D.SMD_UNIT_PRICE,D.SMD_QTY\r\n,C.CUM_NAME\r\n,S.*\r\nFROM TBL_SHIP M INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\nINNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\nINNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\nINNER JOIN TBL_EMPLOYE E ON M.EPY_NO=E.EPY_NO\r\n,TBL_SYS_PARAM S\r\n)T	WHERE T.SMT_STATUS>0\r\n  AND T.SMT_NOT_CLEAN=0	\N	ORDER BY EPY_NO,SMT_DATE,SMT_NO,SMD_SEQNO	{"ReportVersion": "2026.3.3", "ReportGuid": "780376f7b32b4e57b67ed7eee77b9428", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607139+0800)/", "ReportChanged": "/Date(1789097607139+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "c_profit", "NameInSource": "c_profit", "Alia