28	MG_DISCNT01	應收帳款折讓統計表	\N	SELECT A.CUM_NO\r\n  ,B.CUM_NAME\r\n  ,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n  ,COALESCE(SUM(A.SMT_TOTAL),0) TOTAL_AR\r\n  ,COALESCE(SUM(C.ARD_AMOUNT),0) TOTAL_RECEIVED\r\n  ,COALESCE(SUM(A.SMT_NOT_CLEAN),0) TOTAL_NOT_CLEAN\r\n  ,COALESCE(SUM(C.ARD_DISCOUNT),0) TOTAL_DISCOUNT\r\n  ,CASE (COALESCE(SUM(C.ARD_AMOUNT),0)+COALESCE(SUM(C.ARD_DISCOUNT),0))\r\n    WHEN 0 THEN 0\r\n    ELSE\r\n      (COALESCE(SUM(C.ARD_DISCOUNT),0)/(COALESCE(SUM(C.ARD_AMOUNT),0)+COALESCE(SUM(C.ARD_DISCOUNT),0))) * 100\r\n    END Discount_Ratio\r\nFROM TBL_SHIP A\r\nINNER JOIN TBL_CUSTOMER B ON A.CUM_NO=B.CUM_NO\r\nLEFT JOIN (  SELECT C.SMT_NO\r\n                  ,COALESCE(SUM(C.ARD_AMOUNT),0) ARD_AMOUNT\r\n                  ,COALESCE(SUM(C.ARD_DISCOUNT),0) ARD_DISCOUNT\r\n            FROM TBL_AR_RECV_DT C\r\n            GROUP BY C.SMT_NO\r\n          )  C ON A.SMT_NO=C.SMT_NO\r\n,TBL_SYS_PARAM S	WHERE A.SMT_STATUS>0\r\n	GROUP BY A.CUM_NO ,B.CUM_NAME,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n	ORDER BY SUM(C.ARD_DISCOUNT) DESC	{"ReportVersion": "2026.3.3", "ReportGuid": "ab5178ad9d4a4021aa71536668033162", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607025+0800)/", "ReportChanged": "/Date(1789097607025+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, 