20	MG_AP_003	應付帳款統計表	\N	SELECT S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n,M.SUP_NO,C.SUP_NAME,C.SUP_ADVANCE_AMOUNT\r\n,SUM(M.RCV_TOTAL+M.RCV_TAX) C_AMOUNT\r\n,SUM(M.RCV_NOT_CLEAN) C_NOT_CLEAN\r\nFROM TBL_PO_RECV M INNER JOIN TBL_SUPPLIER C ON M.SUP_NO=C.SUP_NO\r\n,TBL_SYS_PARAM S\r\n	WHERE M.RCV_NOT_CLEAN<>0\r\n  AND RCV_STATUS>0  	GROUP BY S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n,M.SUP_NO,C.SUP_NAME,C.SUP_ADVANCE_AMOUNT	\N	{"ReportVersion": "2026.3.3", "ReportGuid": "a3dfbc52915d4a30abff72292a81cefd", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097606839+0800)/", "ReportChanged": "/Date(1789097606839+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}, "1": {"Name": "spr_tel", "NameInSource": "spr_tel", "Alias": "spr_tel", "Type": "System.String"}, "2": {"Name": "spr_fax", "NameInSource": "spr_fax", "Alias": "spr_fax", "Type": "System.String"}, "3": {"Name": "spr_addr", "NameInSource": "spr_addr", "Alias": "spr_addr", "Type": "System.String"}, "4": {"Name": "sup_no", "NameInSource": "sup_no", "Alias": "sup_no", "Type": "System.String"}, "5": {"