29	MG_DISCNT02	應付帳款折讓統計表	\N	SELECT A.SUP_NO\r\n  ,B.SUP_NAME\r\n  ,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR\r\n  ,COALESCE(SUM(A.RCV_TOTAL),0) TOTAL_AP\r\n  ,COALESCE(SUM(C.PAD_AMOUNT),0) TOTAL_PAYED\r\n  ,COALESCE(SUM(A.RCV_NOT_CLEAN),0) TOTAL_NOT_CLEAN\r\n  ,COALESCE(SUM(C.PAD_DISCOUNT),0) TOTAL_DISCOUNT\r\n  ,CASE (COALESCE(SUM(C.PAD_AMOUNT),0)+COALESCE(SUM(C.PAD_DISCOUNT),0))\r\n    WHEN 0 THEN 0\r\n    ELSE\r\n      (COALESCE(SUM(C.PAD_DISCOUNT),0)/(COALESCE(SUM(C.PAD_AMOUNT),0)+COALESCE(SUM(C.PAD_DISCOUNT),0))) * 100\r\n    END Discount_Ratio\r\nFROM TBL_PO_RECV A\r\nINNER JOIN TBL_SUPPLIER B ON A.SUP_NO=B.SUP_NO\r\nLEFT JOIN (  SELECT C.RCV_NO\r\n                  ,COALESCE(SUM(C.PAD_AMOUNT),0) PAD_AMOUNT\r\n                  ,COALESCE(SUM(C.PAD_DISCOUNT),0) PAD_DISCOUNT\r\n            FROM TBL_AP_PAY_DT C\r\n            GROUP BY C.RCV_NO\r\n          )  C ON A.RCV_NO=C.RCV_NO\r\n,TBL_SYS_PARAM S	WHERE A.RCV_STATUS>0	GROUP BY A.SUP_NO ,B.SUP_NAME,S.SPR_COR_NAME,SPR_TEL,SPR_FAX,SPR_ADDR	ORDER BY SUM(C.PAD_DISCOUNT) DESC	{"ReportVersion": "2026.3.3", "ReportGuid": "c21485a57496426e9641f69dd7edb60a", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607046+0800)/", "ReportChanged": "/Date(1789097607046+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "sup_no", "NameInSource": "sup_no", "Alias": "sup_no", "Type": "System.String"}, "1": {"Name": "sup_name", "NameInSource": "sup_name", "Alias": "sup_name", "Type": "System.String"}, "2": {"Name": "spr_cor_name", "NameInSource": "spr_cor_name", "Alias": "spr_cor_name", "Type": "System.String"}, "3": {"Name": "spr_tel", "NameInSource": "spr_tel", "Alias": "spr_tel", "Type": "System.String"}, "4": {"Name": "spr_fax", "NameInSource": "spr_fax", "Alias": "spr_fax", "Type": "System.String"}, "5": {"Name": "spr_addr", "NameInSource": "spr_addr", "Alias": "spr_addr", "Type": "System.String"}, "6": {"Name": "total_ap", "NameInSource": "total_ap", "Alias": "total_ap", "Type": "System.Decimal"}, "7": {"Name": "total_payed", "NameInSource": "total_payed", "Alias": "total_payed", "Type": "System.Decimal"}, "8": {"Name": "total_not_clean", "NameInSource": "total_not_clean", "Alias": "total_not_clean", "Type": "System.Decimal"}, "9": {"Name": "total_discount", "NameInSource": "total_discount", "Alias": "total_discount", "Type": "System.Decimal"}, "10": {"Name": "discount_ratio", "NameInSource": "discount_ratio", "Alias": "discount_ratio", "Type": "System.Decimal"}}}}}, "Pages": {"0": {"Ident": "StiPage", "Name": "Page1", "Guid": "c52f46c0c9254b04b5ff00a37cb9eb6c", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiPageHeaderBand", "Name": "ppHeaderBand1", "Guid": "6d78eb34a9144aaa9f28187289f87760", "CanGrow": true, "ClientRectangle": "0,0.0,19.7379,3.3338", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:", "Components": {"0": {"Ident": "StiText", "Name": "ppLabel2", "Guid": "7dfe69b245524be3bddd59cf2df3981d", "ClientRectangle": "0.635,0.4498,1.7727,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "製表日期："}, "Type": "Expression", "