35	ST_RPT_01-3	市價績效報表	\N	SELECT C_SUB_TOTAL-C_COST C_PROFIT\r\n            ,T.*\r\nFROM\r\n(   SELECT E.EPY_NAME\r\n    ,D.SMD_QTY*SMD_UNIT_PRICE C_SUB_TOTAL\r\n    ,D.SMD_QTY*COALESCE(LAST_INPRICE,D.SMD_COST) C_COST\r\n    ,COALESCE(D.SMD_PRD_NAME,P.PRD_NAME)C_PRD_NAME\r\n    ,LAST_INDATE\r\n    ,M.*\r\n    ,D.SMD_SEQNO,D.PRD_NO,D.SMD_UNIT_PRICE,D.SMD_QTY\r\n    ,C.CUM_NAME\r\n    FROM TBL_SHIP M \r\n    INNER JOIN TBL_SHIP_DT D ON M.SMT_NO=D.SMT_NO\r\n    INNER JOIN TBL_CUSTOMER C ON M.CUM_NO=C.CUM_NO\r\n    INNER JOIN TBL_PRODUCT P ON D.PRD_NO=P.PRD_NO\r\n    INNER JOIN TBL_EMPLOYE E ON M.EPY_NO=E.EPY_NO\r\n    LEFT JOIN \r\n    ( SELECT    RCD.PRD_NO,A.RCV_DATE LAST_INDATE   --找到每個產品的最後進貨價格\r\n                        ,MAX(RCD.RCD_UNIT_PRICE) LAST_INPRICE\r\n        FROM TBL_PO_RECV RCV\r\n        INNER JOIN TBL_PO_RECV_DT RCD ON RCV.RCV_NO = RCD.RCV_NO\r\n        INNER JOIN\r\n        (   SELECT  RCD.PRD_NO          --找到每個產品的最後進貨日\r\n                         ,MAX(RCV.RCV_DATE) RCV_DATE\r\n            FROM TBL_PO_RECV RCV\r\n            INNER JOIN TBL_PO_RECV_DT RCD ON RCV.RCV_NO = RCD.RCV_NO\r\n            GROUP BY RCD.PRD_NO\r\n        ) A ON RCV.RCV_DATE =A.RCV_DATE \r\n                AND RCD.PRD_NO  =A.PRD_NO\r\n        GROUP BY RCD.PRD_NO,A.RCV_DATE      \r\n    ) RCV ON D.PRD_NO   = RCV.PRD_NO        \r\n)T	WHERE T.SMT_STATUS>0\n  AND T.SMT_NOT_CLEAN=0	\N	ORDER BY EPY_NO,SMT_DATE,SMT_NO,SMD_SEQNO	{"ReportVersion": "2026.3.3", "ReportGuid": "4db34f8adc384097874eb2a2f5bd9226", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607193+0800)/", "ReportChanged": "/Date(1789097607193+0800)/", "EngineVersion": "EngineV2", "ReportUnit": "Centimeters", "ScriptLanguage": "CSharp", "UsePlatformDependentScript": false, "CalculationMode": "Interpretation", "Dictionary": {"DataSources": {"0": {"Ident": "StiDataTableSource", "Name": "srpmeta", "NameInSource": "srpmeta", "Alias": "srpmeta", "Columns": {"0": {"Name": "srp_id", "NameInSource": "srp_id", "Alias": "srp_id", "Type": "System.String"}, "1": {"Name": "srp_code", "NameInSource": "srp_code", "Alias": "srp_code", "Type": "System.String"}, "2": {"Name": "srp_name", "NameInSource": "srp_name", "Alias": "srp_name", "Type": "System.String"}, "3": {"Name": "srp_description", "NameInSource": "srp_description", "Alias": "srp_description", "Type": "System.String"}}}, "1": {"Ident": "StiDataTableSource", "Name": "root", "NameInSource": "root", "Alias": "root", "Columns": {"0": {"Name": "c_profit", "NameInSource": "c_profit", "Alias": "c_profit", "Type": "System.Decimal"}, "1": {"Name": "epy_name", "NameInSource": "epy_name", "Alias": "epy_name", "Type": "System.String"}, "2": {"Name": "c_sub_total", "NameInSource": "c_sub_total", "Alias": "c_sub_total", "Type": "System.Decimal"}, "3": {"Name": "c_cost", "NameInSource": "c_cost", "Alias": "c_cost", "Type": "System.Decimal"}, "4": {"Name": "c_prd_name", "NameInSource": "c_prd_name", "Alias": "c_prd_name", "Type": "System.String"}, "5": {"Name": "last_indate", "NameInSource": "last_indate", "Alias": "last_indate", "Type": "System.DateTime"}, "6": {"Name": "smt_no", "NameInSource": "smt_no", "Alias": "smt_no", "Type": "System.String"}, "7": {"Name": "cum_no", "NameInSource": "cum_no", "Alias": "cum_no", "Type": "System.String"}, "8": {"Name": "epy_no", "NameInSource": "epy_no", "Alias": "epy_no", "Type": "System.String"}, "9": {"Name": "car_no", "NameInSource": "car_no", "Alias": "car_no", "Type": "System.String"}, "10": {"Name": "jnl_no", "NameInSource": "jnl_no", "Alias": "jnl_no", "Type": "System.String"}, "11": {"Name": "smt_status", "NameInSource": "smt_status", "Alias": "smt_status", "Type": "System.Int32"}, "12": {"Name": "smt_inv_no", "NameInSource": "smt_inv_no", "Alias": "smt_inv_no", "Type": "System.String"}, "13": {"Name": "smt_date", "NameInSource": "smt_date", "Alias": "smt_date", "Type": "System.DateTime"}, "14": {"Name": "smt_destination", "NameInSource": "smt_destination", "Alias": "smt_destina