ession", "Font": ";10;;", "Border": ";;;;;;;solid:Black", "Brush": "solid:", "TextBrush": "solid:Black"}, "6": {"Ident": "StiHorizontalLinePrimitive", "Name": "ppLine4", "Guid": "c55eba26d9ba4de5a44b207770b546db", "ClientRectangle": "0.0,0.0265,19.7379,0.2117", "Interaction": {"Ident": "StiInteraction"}, "Size": 2, "StartCap": ";;;", "EndCap": ";;;"}, "7": {"Ident": "StiText", "Name": "ppLabel16", "Guid": "3cf30b2c528e46018c50eb51efe4ba71", "ClientRectangle": "14.949,0.8731,1.7727,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "獎金合計："}, "Type": "Expression", "Font": ";10;;", "Border": ";;;;;;;solid:Black", "Brush": "solid:", "TextBrush": "solid:Black", "HorAlignment": "Right"}, "8": {"Ident": "StiText", "Name": "ppDBCalc11", "Guid": "6c3e14d2699e4defb9aebb58d7ed424a", "ClientRectangle": "16.8805,0.8731,1.7198,0.4233", "Interaction": {"Ident": "StiInteraction"}, "Text": {"Value": "{Sum(root.c_bonus_all)}"}, "Type": "Expression", "Font": ";10;;", "Border": ";;;;;;;solid:Black", "Brush": "solid:", "TextBrush": "solid:Black", "HorAlignment": "Right"}}}, "6": {"Ident": "StiFooterBand", "Name": "ppFooterBand1", "Guid": "4b50b566cc35481ca210123179aef1b0", "CanGrow": true, "ClientRectangle": "0,8.6784,19.7379,0.0", "Interaction": {"Ident": "StiInteraction"}, "Border": ";;;;;;;solid:Black", "Brush": "solid:"}}, "PageWidth": 21.0079, "PageHeight": 29.7127}}}
46	ST_RPT_10	運輸人員業績分析表	\N	SELECT A.DELIVER_NO,A.EPY_NAME,A.SMT_DATE,A.TOTAL,B.RETURN_TOTAL\r\nFROM\r\n(  SELECT DELIVER_NO,EPY_NAME,SMT_DATE\r\n  ,SUM(TOTAL) TOTAL\r\n  FROM\r\n  (  SELECT 1 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER1 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER1=C.EPY_NO\r\n    WHERE B.SMD_QTY >0\r\n\r\n    UNION\r\n\r\n    SELECT 2 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER2 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER2=C.EPY_NO\r\n    WHERE B.SMD_QTY >0\r\n  ) A\r\n  GROUP BY DELIVER_NO,EPY_NAME,SMT_DATE\r\n) A\r\nLEFT JOIN\r\n(  SELECT DELIVER_NO,EPY_NAME,SMT_DATE\r\n  ,SUM(TOTAL) RETURN_TOTAL\r\n  FROM\r\n  (\r\n    SELECT 1 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER1 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER1=C.EPY_NO\r\n    WHERE B.SMD_QTY <0\r\n\r\n  UNION\r\n\r\n    SELECT 2 DELIVER ,B.SMD_SEQNO,A.SMT_DELIVER2 DELIVER_NO,C.EPY_NAME,A.SMT_DATE,A.SMT_NO\r\n    ,B.SMD_QTY*B.SMD_UNIT_PRICE*0.5 TOTAL\r\n    FROM TBL_SHIP a\r\n    INNER JOIN TBL_SHIP_DT B ON A.SMT_NO=B.SMT_NO\r\n    INNER JOIN TBL_EMPLOYE C ON A.SMT_DELIVER2=C.EPY_NO\r\n    WHERE B.SMD_QTY <0\r\n  ) A\r\n  GROUP BY DELIVER_NO,EPY_NAME,SMT_DATE\r\n) B\r\nON A.DELIVER_NO=B.DELIVER_NO\r\nAND A.SMT_DATE=B.SMT_DATE	\N	\N	ORDER BY A.DELIVER_NO,A.SMT_DATE 	{"ReportVersion": "2026.3.3", "ReportGuid": "bf6c2613eabb4ed898a1556ee22b6494", "ReportName": "Report", "ReportAlias": "Report", "ReportCreated": "/Date(1789097607422+0800)/", "ReportChanged": "/Date(1789097607422+0800)/", "EngineVersion": "EngineV2", "ReportUnit"